import{_ as e,o as a,c as r,a2 as i}from"./chunks/framework.GbRRgL9t.js";const u=JSON.parse('{"title":"CircleChat 项目简介","description":"","frontmatter":{},"headers":[],"relativePath":"README.md","filePath":"README.md","lastUpdated":1789902237000}'),o={name:"README.md"};function l(d,t,n,s,h,c){return a(),r("div",null,[...t[0]||(t[0]=[i('<h1 id="circlechat-项目简介" tabindex="-1">CircleChat 项目简介 <a class="header-anchor" href="#circlechat-项目简介" aria-label="Permalink to &quot;CircleChat 项目简介&quot;">​</a></h1><p>CircleChat 是一款<strong>自托管的轻量多人聊天服务器</strong>。单进程部署，支持群组 / 私聊，内置好友关系、开放注册审核、在线状态、消息撤回、表情回应、举报处罚与审计日志。服务端<strong>零第三方运行时依赖</strong>（仅依赖 Node.js 内建能力与 <code>node:sqlite</code>）。基于 <a href="https://github.com/CircleChat-Team/CircleChat/blob/main/LICENSE" target="_blank" rel="noreferrer">GPL-3.0</a> 开源。</p><h2 id="定位与特点" tabindex="-1">定位与特点 <a class="header-anchor" href="#定位与特点" aria-label="Permalink to &quot;定位与特点&quot;">​</a></h2><ul><li><strong>自托管</strong>：一套服务即可跑起完整聊天站，适合公益 / 私有服务器。</li><li><strong>零第三方运行时依赖</strong>：后端没有用到任何第三方 npm 运行时依赖，易于审查与审计。</li><li><strong>性能</strong>：页面加载目标在 1 秒内，单进程设计，内存占用低。</li><li><strong>多语言</strong>：界面支持 zh / en / ja 三语。</li><li><strong>可观测</strong>：所有 HTTP 请求与 WebSocket 连接写入 <code>data/access.log</code>（应用层网络监控）。</li><li><strong>轻前端</strong>：Vue 3 + TypeScript + Tailwind 4，构建产物由服务端内部静态服务托管。</li></ul><h2 id="核心能力一览" tabindex="-1">核心能力一览 <a class="header-anchor" href="#核心能力一览" aria-label="Permalink to &quot;核心能力一览&quot;">​</a></h2><table tabindex="0"><thead><tr><th>类别</th><th>能力</th></tr></thead><tbody><tr><td>通讯</td><td>群组聊天、好友私聊、在线状态、正在输入、表情回应、引用回复、消息撤回</td></tr><tr><td>文件</td><td>单次上传 / 分片断点续传、图片 / 音频 / 视频 / 文件 / 合并转发，图片魔数校验</td></tr><tr><td>治理</td><td>开放注册 + 管理员审核、举报、禁言 / 封禁 / IP 封禁、处罚通知、审计日志</td></tr><tr><td>账号</td><td>邮箱注册、会话 Cookie、两步验证（TOTP）、修改密码</td></tr><tr><td>信箱</td><td>系统公告（全局广播）、个人通知（按用户分发，如处罚结果）</td></tr><tr><td>管理</td><td>用户管理、注册审核、举报处理、处罚、文件管理、操作日志</td></tr></tbody></table><h2 id="技术栈" tabindex="-1">技术栈 <a class="header-anchor" href="#技术栈" aria-label="Permalink to &quot;技术栈&quot;">​</a></h2><ul><li><strong>后端</strong>：Node.js（Nitro 运行时），后端逻辑集中在 <code>server/lib/</code>（原 <code>server.js</code> + <code>lib/</code> 的 1:1 迁移）。</li><li><strong>数据</strong>：SQLite（<code>node:sqlite</code>，Node ≥ 22.5 内建），数据库文件 <code>data/chatplus.db</code>。</li><li><strong>前端</strong>：Vue 3 + TypeScript，构建工具 Vite，样式 Tailwind 4。</li><li><strong>实时</strong>：自研 WebSocket 协议（零第三方依赖，自实现握手 / 帧编解码 / 分片 / 掩码 / Ping-Pong）。</li></ul><h2 id="依赖要求" tabindex="-1">依赖要求 <a class="header-anchor" href="#依赖要求" aria-label="Permalink to &quot;依赖要求&quot;">​</a></h2><ul><li><strong>Node.js ≥ 22.5</strong>（使用内建 <code>node:sqlite</code>，低版本启动会崩溃；<code>vite build</code> 需 Node ≥ 20.19）</li></ul><h2 id="文档结构" tabindex="-1">文档结构 <a class="header-anchor" href="#文档结构" aria-label="Permalink to &quot;文档结构&quot;">​</a></h2><ul><li><a href="./getting-started/quickstart.html">快速开始</a>：最短路径跑起来。</li><li><a href="./getting-started/installation.html">生产部署</a>：Nginx / 容器 / 更新服务器。</li><li><a href="./getting-started/configuration.html">配置说明</a>：端口、上传保留、地址分离与内置账号。</li><li><a href="./guide/usage.html">用户指南</a>：普通用户功能手册。</li><li><a href="./guide/administration.html">管理后台</a>：管理员功能手册。</li><li><a href="./api/overview.html">API 参考</a>：HTTP 接口与 WebSocket 协议全量说明。</li></ul><h2 id="许可" tabindex="-1">许可 <a class="header-anchor" href="#许可" aria-label="Permalink to &quot;许可&quot;">​</a></h2><p>本项目以 <a href="https://github.com/CircleChat-Team/CircleChat/blob/main/LICENSE" target="_blank" rel="noreferrer">GNU GPL v3.0</a> 开源。使用、复制、修改与分发请遵守 GPL-3.0 条款；再分发时须附带本许可证并保留许可声明。本项目按「原样」提供，不提供任何担保。</p>',14)])])}const b=e(o,[["render",l]]);export{u as __pageData,b as default};
